		  const sc=bank.filter((c,i)=>bank.indexOf(c)===i&&c.toLowerCase()!==v).map(c=>{const cl=c.toLowerCase(),W=tok(c);let n=0;T.forEach(t=>{if(W.some(w=>w.startsWith(t)))n++});if(cl.startsWith(v))n+=3;return {c,n}}).filter(x=>x.n>0).sort((a,b)=>b.n-a.n).slice(0,4);
