		  const rv=$('#f_role').value,cto=rv==='con'?$('#f_cto').value:null,tm=rv==='team'?[...ROOT.querySelectorAll('[name=f_tm]:checked')].map(x=>x.value):null;
		  if(rv==='team'&&!tm.length){toast('Pick at least one team, or choose another role.');return}
		  const ch=Object.keys(nw).filter(k=>nw[k]!==g[k]);if(JSON.stringify(al)!==JSON.stringify(g.also||[]))ch.push('links');if((cto||'')!==(g.cto||''))ch.push('role');if(tm&&tm.slice().sort().join()!==teamNames(g).slice().sort().join())ch.push('team');
